<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$c=srnu_obtener_cotizacion($id);if(!$c){http_response_code(404);exit('No encontrada');}
function consumir_inventario(PDO $pdo,array $c,int $id):void{
 $st=$pdo->prepare('SELECT inventario_descontado FROM ordenes_trabajo WHERE cotizacion_id=?');$st->execute([$id]);if((int)$st->fetchColumn()===1)return;
 foreach($c['items'] as $it){$cat=(int)($it['catalogo_id']??0);if(!$cat)continue;$r=$pdo->prepare('SELECT ci.*,i.nombre,i.costo_unitario FROM catalogo_insumos ci JOIN inventario i ON i.id=ci.inventario_id WHERE ci.catalogo_id=?');$r->execute([$cat]);foreach($r as $ins){$qty=round((float)$ins['cantidad']*(float)$it['cantidad'],3);if($qty<=0)continue;$pdo->prepare('UPDATE inventario SET stock=stock-? WHERE id=?')->execute([$qty,$ins['inventario_id']]);$pdo->prepare("INSERT INTO movimientos_inventario(inventario_id,tipo,cantidad,costo_unitario,referencia_tipo,referencia_id,notas) VALUES(?, 'Consumo orden', ?, ?, 'Cotización', ?, ?)")->execute([$ins['inventario_id'],-$qty,$ins['costo_unitario'],$id,'Consumo por '.$it['concepto']]);}}
 $pdo->prepare('UPDATE ordenes_trabajo SET inventario_descontado=1 WHERE cotizacion_id=?')->execute([$id]);
}
function crear_postventa_y_garantias(PDO $pdo,array $c,int $id):void{
 foreach($c['items'] as $it){$m=(int)($it['garantia_meses']??0);if($m<=0)continue;$chk=$pdo->prepare('SELECT id,fecha_fin FROM garantias WHERE cotizacion_id=? AND item_id=?');$chk->execute([$id,$it['id']]);$g=$chk->fetch();if(!$g){$ini=date('Y-m-d');$fin=date('Y-m-d',strtotime('+'.$m.' months'));$pdo->prepare('INSERT INTO garantias(cotizacion_id,item_id,concepto,fecha_inicio,fecha_fin,estado) VALUES(?,?,?,?,?,?)')->execute([$id,$it['id'],$it['concepto'],$ini,$fin,'Vigente']);$gid=(int)$pdo->lastInsertId();}else{$gid=(int)$g['id'];$fin=$g['fecha_fin'];}$chk2=$pdo->prepare("SELECT id FROM postventa_recordatorios WHERE garantia_id=? AND tipo='Garantía'");$chk2->execute([$gid]);if(!$chk2->fetch()){$record=date('Y-m-d',max(time(),strtotime($fin.' -30 days')));$pdo->prepare("INSERT INTO postventa_recordatorios(cotizacion_id,garantia_id,tipo,fecha_recordatorio,descripcion,estado) VALUES(?,?,'Garantía',?,?,'Pendiente')")->execute([$id,$gid,$record,'Revisar garantía próxima a vencer: '.$it['concepto']]);}}
 $chk=$pdo->prepare("SELECT id FROM postventa_recordatorios WHERE cotizacion_id=? AND tipo='Seguimiento' AND descripcion='Seguimiento 30 días después de entrega'");$chk->execute([$id]);if(!$chk->fetch())$pdo->prepare("INSERT INTO postventa_recordatorios(cotizacion_id,tipo,fecha_recordatorio,descripcion,estado) VALUES(?,'Seguimiento',?,'Seguimiento 30 días después de entrega','Pendiente')")->execute([$id,date('Y-m-d',strtotime('+30 days'))]);
}
if($_SERVER['REQUEST_METHOD']==='POST'){$estado=epost('estado','Vehículo recibido');$notas=epost('notas');$pdo->prepare("INSERT INTO ordenes_trabajo(cotizacion_id,estado,notas) VALUES(?,?,?) ON DUPLICATE KEY UPDATE estado=VALUES(estado),notas=VALUES(notas),updated_at=NOW()")->execute([$id,$estado,$notas]);$pdo->prepare('UPDATE cotizaciones SET estado=?,updated_at=NOW() WHERE id=?')->execute([$estado,$id]);if(in_array($estado,['En proceso','Terminado','Entregado'],true))consumir_inventario($pdo,$c,$id);if($estado==='Entregado')crear_postventa_y_garantias($pdo,$c,$id);ego('orden_trabajo.php?id='.$id);}
$st=$pdo->prepare('SELECT * FROM ordenes_trabajo WHERE cotizacion_id=?');$st->execute([$id]);$o=$st->fetch()?:['estado'=>$c['estado'],'notas'=>'','inventario_descontado'=>0];$hasOver=false;foreach($c['items'] as $it){if(($it['tipo_entrega']??'inmediata')==='sobre_pedido'){$hasOver=true;break;}}$short=[];foreach($c['items'] as $it){if(empty($it['catalogo_id']))continue;$r=$pdo->prepare('SELECT i.nombre,i.stock,i.unidad,ci.cantidad FROM catalogo_insumos ci JOIN inventario i ON i.id=ci.inventario_id WHERE ci.catalogo_id=?');$r->execute([(int)$it['catalogo_id']]);foreach($r as $ins){$req=(float)$ins['cantidad']*(float)$it['cantidad'];if((float)$ins['stock']<$req)$short[]=['nombre'=>$ins['nombre'],'stock'=>$ins['stock'],'req'=>$req,'unidad'=>$ins['unidad']];}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orden · <?=eh($c['folio'])?></title><?=srnu_ui_head()?><style>@media print{.no-print,.srnu-appbar{display:none!important}body{background:#fff!important}}</style></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading no-print"><div><h1>Orden de trabajo</h1><p><?=eh($c['folio'])?> · <?=eh($c['cliente'])?> · <?=eh($c['vehiculo'])?></p></div><div class="toolbar"><a class="btn light" href="cotizaciones.php">← Cotizaciones</a><a class="btn light" href="recepcion.php?id=<?=$id?>">Recepción</a><a class="btn light" href="agenda.php?cotizacion_id=<?=$id?>">Agenda</a><?php if($hasOver):?><a class="btn orange" href="compras.php?cotizacion_id=<?=$id?>">Pedido / compra</a><?php endif;?><button class="btn blue" onclick="print()">Imprimir</button></div></div><?php if($short):?><section class="panel no-print" style="padding:16px;border-color:#fecaca!important"><h3>⚠ Insumos insuficientes</h3><?php foreach($short as $s):?><p><?=eh($s['nombre'])?>: stock <?=number_format((float)$s['stock'],3)?>, requiere <?=number_format((float)$s['req'],3)?> <?=eh($s['unidad'])?></p><?php endforeach;?><a class="btn orange" href="inventario.php">Ir a inventario</a></section><?php endif;?><section class="panel" style="padding:20px"><h1 style="color:#0f172a!important">Orden <?=eh($c['folio'])?></h1><p><b><?=eh($c['cliente'])?></b> · <?=eh($c['vehiculo'])?> · <?=eh($c['telefono'])?></p><table><thead><tr><th>Concepto</th><th>Cant.</th><th>Disponibilidad</th><th>Responsable(s)</th></tr></thead><tbody><?php foreach($c['items'] as $it):?><tr><td><?=eh($it['concepto'])?></td><td><?=eh($it['cantidad'])?></td><td><?php if(($it['tipo_entrega']??'inmediata')==='sobre_pedido'):?><span class="badge badge-orange">Sobre pedido</span><div class="muted">Llegada: <?=(int)($it['dias_entrega_estimada']??0)?> días aprox.</div><?php else:?><span class="badge badge-green">Entrega inmediata</span><?php endif;?></td><td><?=!empty($it['responsable_sergio'])?'Sergio ':''?><?=!empty($it['responsable_ricardo'])?'Ricardo ':''?><?=!empty($it['responsable_tomas'])?'Tomás':''?></td></tr><?php endforeach;?></tbody></table><?php $tgMin=(int)($c['dias_trabajo_general_min']??0);$tgMax=(int)($c['dias_trabajo_general_max']??0);if($tgMin>0||$tgMax>0):?><div class="card" style="margin-top:14px;padding:14px"><b>Tiempo estimado total de trabajo:</b> <?=$tgMin>0&&$tgMax>0?($tgMin.'–'.$tgMax):($tgMax?:$tgMin)?> días<?php if($hasOver):?>, una vez recibidas todas las piezas necesarias.<?php endif;?></div><?php endif;?><?php if(!empty($o['inventario_descontado'])):?><p class="no-print"><span class="badge badge-green">✓ Inventario descontado</span></p><?php endif;?></section><section class="panel no-print" style="padding:18px;margin-top:16px"><form method="post" class="erp-form"><input type="hidden" name="id" value="<?=$id?>"><label>Estado<select name="estado"><?php foreach(['Vehículo recibido','En proceso','Terminado','Entregado','Cancelado'] as $e):?><option <?=$o['estado']===$e?'selected':''?>><?=$e?></option><?php endforeach;?></select></label><label>Notas internas<textarea name="notas"><?=eh($o['notas'])?></textarea></label><button class="btn blue">Guardar orden</button></form><p class="muted">Al pasar a <b>En proceso</b> se descuentan los insumos configurados una sola vez. Al marcar <b>Entregado</b> se crean garantías y recordatorios postventa.</p></section></main></body></html>
